// Configuration of the OPSYS context engine (OPSYS-AI PLAN T3.3-suite, ADR-0010 decisions 3 and 4).
//
// Read from `<config dir>/opsys/contexte.json`, next to `metier.json` and `roles.json`
// (`src/gateway/opsys-metier-config.ts`, `src/gateway/opsys-device-roles.ts`). Like them it is
// deliberately NOT part of the Zod-validated `OpenClawConfig`: the root schema is strict, and adding
// a key would also move the generated config baseline of an upstream surface OPSYS does not own.
// The file is GENERATED by `src/opsys/openclaw.py` (`opsys openclaw configurer
// --contexte-entreprise ...`); the same command selects this engine in `plugins.slots.contextEngine`.
//
// OFF by default: a missing file, or a file without `"actif": true`, changes nothing to any agent
// turn. Fail-closed once enabled: a malformed value is reported as `invalid` and the engine says so
// in the turn's context (see `opsys-contexte-engine.ts`); it is never replaced by an invented default.
//
// File format (keys are French like the other OPSYS fragments):
//   {
//     "actif": true,                                   // required, must be exactly true
//     "serveur": "opsys_m10",                          // key of the M10 server in `mcp.servers`
//     "outil_paquet": "m10_paquet_contexte_affaire",   // read tool (T0), PREFLIGHT
//     "outil_depot": "m10_deposer_faits_candidats",    // deposit tool, POSTFLIGHT
//     "delai_ms": 4000,                                // bound of ONE call to the engine
//     "agents": {                                      // required, non-empty
//       "m03-estimation": { "depot": ["m3_estimer_projet"] }
//     }
//   }
// `agents` names the agents that get the packet before their turn; `depot` lists the department
// tools whose results are handed to M10 after the turn (empty or absent: nothing is deposited).
import fs from "node:fs";
import path from "node:path";
import { isValidAgentId, normalizeAgentId } from "@openclaw/normalization-core/agent-id";
import { asSafeIntegerInRange } from "@openclaw/normalization-core/number-coercion";
import { isRecord } from "@openclaw/normalization-core/record-coerce";
import { resolveOpsysDir } from "../gateway/opsys-metier-config.js";
import { formatErrorMessage } from "../infra/errors.js";

export const OPSYS_CONTEXTE_CONFIG_FILENAME = "contexte.json";

const DEFAULT_SERVER = "opsys_m10";
const DEFAULT_PACKET_TOOL = "m10_paquet_contexte_affaire";
const DEFAULT_DEPOSIT_TOOL = "m10_deposer_faits_candidats";
const DEFAULT_TIMEOUT_MS = 4_000;
const TIMEOUT_RANGE = { min: 100, max: 30_000 };
const SERVER_PATTERN = /^[A-Za-z0-9_-]{1,64}$/u;
const TOOL_PATTERN = /^m(?:10|[1-9])_[a-z][a-z0-9_]{1,60}$/u;

export type OpsysContexteConfig = Readonly<{
  /** Key of the M10 server in `mcp.servers` (its URL and token header are the existing ones). */
  server: string;
  packetTool: string;
  depositTool: string;
  /** Bound of ONE call to the engine: the turn never waits longer for it. */
  timeoutMs: number;
  /** Agent id -> department tools whose results are deposited after the turn. */
  agents: ReadonlyMap<string, readonly string[]>;
}>;

export type OpsysContexteConfigResult =
  /** No `contexte.json`: the engine is transparent. */
  | { kind: "absent" }
  /** The file exists without `"actif": true`: the engine is transparent. */
  | { kind: "disabled" }
  /** The operator asked for the engine but the file cannot be trusted. */
  | { kind: "invalid"; reason: string }
  | { kind: "enabled"; config: OpsysContexteConfig };

function invalid(reason: string): OpsysContexteConfigResult {
  return { kind: "invalid", reason };
}

function readName(
  root: Record<string, unknown>,
  key: string,
  fallback: string,
  pattern: RegExp,
): string | undefined {
  const raw = root[key];
  if (raw === undefined) {
    return fallback;
  }
  return typeof raw === "string" && pattern.test(raw) ? raw : undefined;
}

function parseAgents(
  raw: unknown,
): { ok: true; agents: Map<string, readonly string[]> } | { ok: false; reason: string } {
  if (!isRecord(raw) || Object.keys(raw).length === 0) {
    return { ok: false, reason: '"agents" must map at least one agent id to its settings' };
  }
  const agents = new Map<string, readonly string[]>();
  for (const [rawId, settings] of Object.entries(raw)) {
    if (!isValidAgentId(rawId)) {
      return { ok: false, reason: `"agents" has an invalid agent id: ${JSON.stringify(rawId)}` };
    }
    const agentId = normalizeAgentId(rawId);
    if (agents.has(agentId)) {
      return { ok: false, reason: `"agents" lists ${JSON.stringify(agentId)} twice` };
    }
    if (!isRecord(settings)) {
      return { ok: false, reason: `"agents.${agentId}" must be an object` };
    }
    const deposit: unknown = settings.depot === undefined ? [] : settings.depot;
    if (
      !Array.isArray(deposit) ||
      !deposit.every((tool): tool is string => typeof tool === "string" && TOOL_PATTERN.test(tool))
    ) {
      return {
        ok: false,
        reason: `"agents.${agentId}.depot" must list department tool names such as m3_estimer_projet`,
      };
    }
    agents.set(agentId, [...new Set(deposit)]);
  }
  return { ok: true, agents };
}

/** Validates the parsed JSON of `contexte.json`. Exported for tests. */
export function parseOpsysContexteConfig(raw: unknown): OpsysContexteConfigResult {
  if (!isRecord(raw)) {
    return invalid("contexte.json must contain a JSON object");
  }
  if (raw.actif !== true) {
    return { kind: "disabled" };
  }
  const server = readName(raw, "serveur", DEFAULT_SERVER, SERVER_PATTERN);
  if (server === undefined) {
    return invalid('"serveur" must be the name of an entry of mcp.servers');
  }
  const packetTool = readName(raw, "outil_paquet", DEFAULT_PACKET_TOOL, TOOL_PATTERN);
  if (packetTool === undefined) {
    return invalid('"outil_paquet" must be a department tool name such as m10_paquet_contexte_affaire');
  }
  const depositTool = readName(raw, "outil_depot", DEFAULT_DEPOSIT_TOOL, TOOL_PATTERN);
  if (depositTool === undefined) {
    return invalid('"outil_depot" must be a department tool name such as m10_deposer_faits_candidats');
  }
  const timeoutMs =
    raw.delai_ms === undefined
      ? DEFAULT_TIMEOUT_MS
      : asSafeIntegerInRange(raw.delai_ms, TIMEOUT_RANGE);
  if (timeoutMs === undefined) {
    return invalid(
      `"delai_ms" must be an integer from ${String(TIMEOUT_RANGE.min)} to ${String(TIMEOUT_RANGE.max)}`,
    );
  }
  const agents = parseAgents(raw.agents);
  if (!agents.ok) {
    return invalid(agents.reason);
  }
  return {
    kind: "enabled",
    config: { server, packetTool, depositTool, timeoutMs, agents: agents.agents },
  };
}

/**
 * Reads `<opsys dir>/contexte.json`. `dir` overrides the default lookup (tests only; production
 * omits it). The read is synchronous and tiny: it runs once per engine resolution.
 */
export function readOpsysContexteConfig(
  params: { dir?: string; env?: NodeJS.ProcessEnv } = {},
): OpsysContexteConfigResult {
  const file = path.join(params.dir ?? resolveOpsysDir(params.env), OPSYS_CONTEXTE_CONFIG_FILENAME);
  let text: string;
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return { kind: "absent" };
    }
    return invalid(`cannot read ${file}: ${formatErrorMessage(error)}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (error) {
    return invalid(`${file} is not valid JSON: ${formatErrorMessage(error)}`);
  }
  return parseOpsysContexteConfig(parsed);
}
